from typing import List

class Solution:
    def longestSubarray(self, nums: List[int]) -> int:
        best = 0
        for delete in range(len(nums)):
            current = 0
            for i, value in enumerate(nums):
                if i == delete:
                    continue
                if value == 1:
                    current += 1
                    best = max(best, current)
                else:
                    current = 0
        return best

