from typing import List

class Solution:
    def longestSubarray(self, nums: List[int]) -> int:
        left = 0
        last_zero = -1
        best = 0
        for right, value in enumerate(nums):
            if value == 0:
                # A second zero forces the window to start after the prior zero.
                left = last_zero + 1
                last_zero = right
            best = max(best, right - left)
        return best

